import React from 'react';
import { Card, Table, Button, Space, Tag } from 'antd';

const PurchaseOrders = () => {
  const columns = [
    { title: 'PO Number', dataIndex: 'po_number', key: 'po_number' },
    { title: 'Vendor', dataIndex: 'vendor_name', key: 'vendor_name' },
    { title: 'Total Amount', dataIndex: 'total_amount', key: 'total_amount' },
    { title: 'Status', dataIndex: 'status', key: 'status', render: (status) => <Tag>{status}</Tag> },
    { title: 'Created Date', dataIndex: 'created_at', key: 'created_at' }
  ];

  return (
    <div style={{ padding: '24px' }}>
      <h1>Purchase Orders</h1>
      <Card>
        <Space style={{ marginBottom: 16 }}>
          <Button type="primary">Create PO</Button>
        </Space>
        <Table columns={columns} dataSource={[]} />
      </Card>
    </div>
  );
};

export default PurchaseOrders;