import React, { useState } from 'react';
import { Form, Input, Button, Card, Tabs, message, Row, Col } from 'antd';
import { UserOutlined, LockOutlined, MailOutlined, ShopOutlined } from '@ant-design/icons';
import { useAuth } from '../hooks/useAuth';

const { TabPane } = Tabs;

const Login = () => {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('login');
  const { login, register } = useAuth();

  const onLogin = async (values) => {
    setLoading(true);
    try {
      await login(values);
    } finally {
      setLoading(false);
    }
  };

  const onRegister = async (values) => {
    setLoading(true);
    try {
      const result = await register(values);
      if (result.success) {
        setActiveTab('login');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ 
      minHeight: '100vh', 
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <Row justify="center" style={{ width: '100%' }}>
        <Col xs={24} sm={20} md={16} lg={12} xl={8}>
          <Card
            style={{
              boxShadow: '0 10px 30px rgba(0,0,0,0.3)',
              borderRadius: '10px'
            }}
          >
            <div style={{ textAlign: 'center', marginBottom: '30px' }}>
              <h1 style={{ 
                fontSize: '28px', 
                fontWeight: 'bold',
                color: '#1890ff',
                marginBottom: '8px'
              }}>
                IMS SEPCUNE
              </h1>
              <p style={{ color: '#666', fontSize: '16px' }}>
                Inventory Management System
              </p>
            </div>

            <Tabs 
              activeKey={activeTab} 
              onChange={setActiveTab}
              centered
              size="large"
              items={[
                {
                  key: 'login',
                  label: 'Login',
                  children: (
                    <Form
                      name="login"
                      onFinish={onLogin}
                      layout="vertical"
                      size="large"
                    >
                      <Form.Item
                        name="email"
                        label="Email"
                        rules={[
                          { required: true, message: 'Please input your email!' },
                          { type: 'email', message: 'Please enter a valid email!' }
                        ]}
                      >
                        <Input 
                          prefix={<MailOutlined />} 
                          placeholder="Enter your email"
                        />
                      </Form.Item>

                      <Form.Item
                        name="password"
                        label="Password"
                        rules={[{ required: true, message: 'Please input your password!' }]}
                      >
                        <Input.Password 
                          prefix={<LockOutlined />} 
                          placeholder="Enter your password"
                        />
                      </Form.Item>

                      <Form.Item
                        name="subdomain"
                        label="Company Subdomain (Optional)"
                      >
                        <Input 
                          prefix={<ShopOutlined />} 
                          placeholder="your-company"
                          suffix=".ims-sepcune.com"
                        />
                      </Form.Item>

                      <Form.Item>
                        <Button 
                          type="primary" 
                          htmlType="submit" 
                          loading={loading}
                          block
                          style={{ height: '45px', fontSize: '16px' }}
                        >
                          Sign In
                        </Button>
                      </Form.Item>
                    </Form>
                  )
                },
                {
                  key: 'register',
                  label: 'Register',
                  children: (
                    <Form
                      name="register"
                      onFinish={onRegister}
                      layout="vertical"
                      size="large"
                    >
                      <Form.Item
                        name="name"
                        label="Company Name"
                        rules={[{ required: true, message: 'Please input company name!' }]}
                      >
                        <Input 
                          prefix={<ShopOutlined />} 
                          placeholder="Your Company Name"
                        />
                      </Form.Item>

                      <Form.Item
                        name="subdomain"
                        label="Subdomain"
                        rules={[
                          { required: true, message: 'Please input subdomain!' },
                          { pattern: /^[a-zA-Z0-9-]+$/, message: 'Only letters, numbers, and hyphens allowed!' }
                        ]}
                      >
                        <Input 
                          placeholder="your-company"
                          suffix=".ims-sepcune.com"
                        />
                      </Form.Item>

                      <Row gutter={16}>
                        <Col span={12}>
                          <Form.Item
                            name="adminFirstName"
                            label="First Name"
                            rules={[{ required: true, message: 'Please input first name!' }]}
                          >
                            <Input 
                              prefix={<UserOutlined />} 
                              placeholder="First Name"
                            />
                          </Form.Item>
                        </Col>
                        <Col span={12}>
                          <Form.Item
                            name="adminLastName"
                            label="Last Name"
                            rules={[{ required: true, message: 'Please input last name!' }]}
                          >
                            <Input 
                              prefix={<UserOutlined />} 
                              placeholder="Last Name"
                            />
                          </Form.Item>
                        </Col>
                      </Row>

                      <Form.Item
                        name="adminEmail"
                        label="Admin Email"
                        rules={[
                          { required: true, message: 'Please input admin email!' },
                          { type: 'email', message: 'Please enter a valid email!' }
                        ]}
                      >
                        <Input 
                          prefix={<MailOutlined />} 
                          placeholder="admin@yourcompany.com"
                        />
                      </Form.Item>

                      <Form.Item
                        name="adminPassword"
                        label="Password"
                        rules={[
                          { required: true, message: 'Please input password!' },
                          { min: 8, message: 'Password must be at least 8 characters!' }
                        ]}
                      >
                        <Input.Password 
                          prefix={<LockOutlined />} 
                          placeholder="Create a strong password"
                        />
                      </Form.Item>

                      <Form.Item>
                        <Button 
                          type="primary" 
                          htmlType="submit" 
                          loading={loading}
                          block
                          style={{ height: '45px', fontSize: '16px' }}
                        >
                          Create Account
                        </Button>
                      </Form.Item>
                    </Form>
                  )
                }
              ]}
            />
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Login;